#include <stdio.h>

static inline int min(int a, int b) {
    return a < b ? a : b;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            int val = min(min(i, n - i + 1), min(j, n - j + 1));
            printf("%d%c", val, (j == n) ? '\n' : ' ');
        }
    }

    return 0;
}
